test('explicit old source version supersedes current list, extra accurate declarations append in original order', async () => { const h = harness(); await h.ready; const old = material('first', 'older first', 'historical', 1), absent = material('absent', 'absent source', 'reference', 3); h.sourceHistory.set('first/1', old); h.sourceHistory.set('absent/3', absent); h.sourceBytes.set(old.sha256, 'older first'); h.sourceBytes.set(absent.sha256, 'absent source'); h.state.page.view.assistant!.source_prospectuses = [prospectus(old), prospectus(absent)]; h.state.server = { ...structuredClone(h.state.page.view), version: 7 }; await h.recache(); const e = await h.prepare(); assert.deepEqual(e.items.map(i => [i.sourceMaterial.material_id, i.sourceMaterial.material_version]), [['first', 1], ['second', 2], ['absent', 3]]); const r = await h.helper.resume(e.id); assert.equal(r.state, 'complete'); assert.deepEqual(count(h, 'download').map(c => c.body), [{ materialId: 'first', version: 1 }, { materialId: 'second', version: 2 }, { materialId: 'absent', version: 3 }]); assert.deepEqual(r.envelope.mappedSources!.map(s => s.issuer_name), ['原稿发行人', '原稿发行人']); });
