test('update target from actual review source follows same frozen batch contract', async () => { const h = harness(); await h.ready; h.state.source.kind = 'review'; h.state.page.view.assistant!.action!.business = 'update'; h.state.server = { ...structuredClone(h.state.page.view), version: 7 }; await h.recache(); const e = await h.prepare(), r = await h.helper.resume(e.id); assert.equal(r.state, 'complete'); assert.equal(r.targetData!.project.kind, 'update'); });
test('foreign same-topic journal introduced at final marker blocks the original view API', async () => { const h = harness(), e = await h.prepare(); h.store.beforeSet = (key, raw) => { if (key.startsWith('bb-assistant-project-copy-v1:') && JSON.parse(raw).stage === 'view_unknown') h.store.data.set('bb-assistant-template-upload-v1:owner:other-scope:topic:foreign', '{}'); }; await assert.rejects(h.helper.resume(e.id)); assert.equal(count(h, 'view').length, 0); assert.equal(h.helper.list()[0].stage, 'view_unknown'); });
test('status callback runtime change cannot advance from original pending slot to session create', async () => { const h = harness(), e = await h.prepare(); await assert.rejects(h.helper.resume(e.id, { status: () => { h.state.page.runtime.uncertain = true; } })); assert.equal(count(h, 'upload-create').length, 0); assert.equal(count(h, 'bytes').length, 0); });
test('progress callback new D halts after bytes without a completion/member/PATCH/view request', async () => { const h = harness(), e = await h.prepare(); await assert.rejects(h.helper.resume(e.id, { progress: () => { h.state.page.dirty = true; h.state.page.generation++; h.state.page.view.unsent_content = 'new progress D'; } })); assert.equal(count(h, 'bytes').length, 1); assert.equal(count(h, 'complete').length, 0); assert.equal(count(h, 'member').length, 0); assert.equal(count(h, 'patch').length, 0); assert.equal(count(h, 'view').length, 0); });
test('accepted view with unavailable observation then refreshed exact S retains full fresh runtime and completes read-only without apply', async () => { const { h, e } = await lostViewObservation(), originalCache = h.cache.read('topic', 'actual-project'), current = readServerPage(h, e), before = writes(h).length; assert.deepEqual(originalCache, e.baseCache); const r = await h.make().reconcile(e.id); assert.equal(r.state, 'complete'); assert.equal(r.applyToPage, false); assert.equal(r.envelope.localCacheResult, 'preserved'); assert.deepEqual(h.cache.read('topic', 'actual-project')!.snapshot, current); assert.deepEqual(h.state.page, current); assert.equal(writes(h).length, before); assert.equal(count(h, 'view').length, 1); assert.equal(count(h, 'patch').length, 1); assert.deepEqual(h.helper.list(), []); });
for (const changed of ['dirty', 'conflict', 'foreign-view'] as const) test('fresh server-page retention refuses ' + changed + ' rather than expanding candidate acceptance', async () => { const { h, e } = await lostViewObservation(); readServerPage(h, e); if (changed === 'foreign-view') h.state.page.view.unsent_content = 'different current view'; else h.state.page[changed] = true; const before = writes(h).length; await assert.rejects(h.make().reconcile(e.id)); assert.deepEqual(h.cache.read('topic', 'actual-project'), e.baseCache); assert.equal(h.helper.list()[0].stage, 'cleanup_pending'); assert.equal(h.helper.list()[0].localCacheResult, 'preserved'); assert.equal(h.helper.transportRecords().length, 2); assert.equal(writes(h).length, before); });
test('refreshed exact S cannot replace another page full D in active cache', async () => { const { h, e } = await lostViewObservation(); const foreign = structuredClone(e.basePage); foreign.dirty = true; foreign.conflict = true; foreign.generation++; foreign.view.unsent_content = 'another page full D'; await h.cache.merge('topic', 'actual-project', e.baseCache, foreign); const durable = h.cache.read('topic', 'actual-project'); readServerPage(h, e); const before = writes(h).length; await assert.rejects(h.make().reconcile(e.id)); assert.deepEqual(h.cache.read('topic', 'actual-project'), durable); assert.equal(h.helper.list()[0].stage, 'cleanup_pending'); assert.equal(h.helper.transportRecords().length, 2); assert.equal(writes(h).length, before); });
test('new full D during exact refreshed S cache persistence keeps cleanup proof and cores until D is durable', async () => { const { h, e } = await lostViewObservation(); readServerPage(h, e); h.store.beforeSet = (key, raw) => { if (key.startsWith('bb-assistant-view-v1:') && JSON.parse(raw).snapshot.version === 8) { h.state.page.dirty = true; h.state.page.generation++; h.state.page.runtime.generation++; h.state.page.view.unsent_content = 'new D during fresh cache write'; } }; const before = writes(h).length; await assert.rejects(h.make().reconcile(e.id)); assert.equal(h.helper.list()[0].stage, 'cleanup_pending'); assert.equal(h.helper.list()[0].observedView!.version, 8); assert.equal(h.helper.transportRecords().length, 2); assert.equal(h.state.page.view.unsent_content, 'new D during fresh cache write'); assert.equal(writes(h).length, before); h.store.beforeSet = undefined; await h.recache(); const r = await h.make().reconcile(e.id); assert.equal(r.state, 'complete'); assert.equal(r.applyToPage, false); assert.equal(h.cache.read('topic', 'actual-project')!.snapshot.view.unsent_content, 'new D during fresh cache write'); assert.equal(writes(h).length, before); });
test('cleanup refresh can retain exact S with newly read target runtime while keeping its original B-to-S cache proof', async () => { const h = harness(), e = await h.prepare(); h.store.beforeRemove = key => { if (key.startsWith('bondbuddy:upload-recovery:v1:')) throw new Error('quota'); }; await assert.rejects(h.helper.resume(e.id)); const proof = structuredClone(h.cache.read('topic', 'actual-project')!.proof), current = readServerPage(h, e); h.store.beforeRemove = undefined; const before = h.calls.length, r = await h.make().resume(e.id); assert.equal(r.state, 'complete'); assert.equal(r.applyToPage, false); assert.equal(r.envelope.localCacheResult, 'preserved'); assert.deepEqual(h.cache.read('topic', 'actual-project')!.snapshot, current); assert.deepEqual(h.cache.read('topic', 'actual-project')!.proof, proof); assert.equal(h.calls.length, before); });
